-- A person's grade is dated: a person may have several grades, each in force from its from-date until
-- the next one's. The first grade a person was given has no from-date: it applies from the beginning of
-- time. A person has at most one grade per from-date (and at most one with none).
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE,
    grade     VARCHAR(1) NOT NULL
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, from_date, grade) SELECT id, NULL, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate at
-- that moment. Later changes to rates do not alter it. None while the claim is not settled, or when
-- the grade had no rate when it was settled.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);

        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFixed = false;
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim.getStatus())) {
                claim.unbind();
                continue;
            }
            BigDecimal fixed = claim.getSettledDue() != null ? claim.getSettledDue() : claim.getStatedDue();
            BigDecimal figure = fixed != null ? fixed
                    : Rate.inForceOn(ratesOf(sheetRates, person.gradeOn(claim.getDate())), claim.getDate())
                            .map(rate -> ClaimService.floored(ClaimService.dueOn(claim.getAmount(), rate.getRate()),
                                    sheet.getFloor()))
                            .orElse(null);
            anyFixed |= fixed != null;
            grades.add(person.gradeOn(claim.getDate()));
            total = figure == null ? total : total.add(figure).add(ClaimService.lateCharge(claim, figure, sheet));
            claim.bind(figure);
            counted++;
        }
        // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade any
        // of their claims that count is at, and no fixed figure, the person has no due-total.
        boolean anyRate = grades.stream().anyMatch(g -> Rate.inForceOn(ratesOf(sheetRates, g), today).isPresent());
        String dueTotal = !anyRate && !anyFixed ? "n/a" : total.toPlainString();
        claims.saveAllAndFlush(theirs);

    /** The rates of one grade among a sheet's. */
    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
    }

    /** A claim's due: its settled figure, else its stated one, else its amount at the rate in force on its date of
     *  its person's grade in force on that date, raised to the sheet's floor; an overdue claim's late charge is added on top of the figure. */
    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, Sheet sheet) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal floor = sheet == null ? null : sheet.getFloor();
        BigDecimal figure = claim.getStatedDue() != null ? claim.getStatedDue()
                : Rate.inForceOn(gradeRates, claim.getDate())
                        .map(rate -> ClaimService.floored(ClaimService.dueOn(claim.getAmount(), rate.getRate()), floor))
                        .orElse(null);
        return figure == null || sheet == null ? figure : figure.add(ClaimService.lateCharge(claim, figure, sheet));
    }
}
        this.claims = claims;
    }

    /**
     * Add a DRAFT claim of {@code amount}, dated the sheet's today with an empty note, for the person
     * whose name matches {@code name} (trimmed, ignoring case); one not on the sheet is added first with
     * grade A. One change: when the claim is refused the person is not added and nothing is recorded.
     */
    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person existing = people.findBySheetIdAndNameIgnoreCase(sheetId, name.trim()).orElse(null);
        Person person = existing != null ? existing : personService.add(sheetId, user, name, NEW_PERSON_GRADE);
        Claim claim = claims.add(sheetId, user, person.getId(), amount, null, "");
        return new Added(person, existing == null, claim);
    }
}

